// 启动游戏进程
void 登录页面类::启动游戏进程()
{
	// 获取当前目录
	TCHAR 当前路径[MAX_PATH];
	GetCurrentDirectory(MAX_PATH, 当前路径);

	// 构建游戏路径
	CString 游戏路径;
	游戏路径.Format(_T("%s\\nage.bin"), 当前路径);

	// 检查文件是否存在
	if (GetFileAttributes(游戏路径) == INVALID_FILE_ATTRIBUTES)
	{
		MessageBox(_T("找不到游戏文件 nage.bin"), _T("错误"), MB_ICONERROR);
		return;
	}

	// 构建命令行
	CString 命令行;
	命令行.Format(_T("\"%s\" 1 0 0"), 游戏路径);

	// 启动游戏进程
	STARTUPINFO si = { sizeof(STARTUPINFO) };
	PROCESS_INFORMATION pi;
	if (CreateProcess(NULL, 命令行.GetBuffer(), NULL, NULL, FALSE, 0, NULL, NULL, &si, &pi))
	{
		// 关闭句柄
		CloseHandle(pi.hProcess);
		CloseHandle(pi.hThread);
		命令行.ReleaseBuffer();
	}
	else
	{
		DWORD 错误码 = GetLastError();
		CString 错误信息;
		错误信息.Format(_T("启动游戏失败，错误码：%d"), 错误码);
		MessageBox(错误信息, _T("错误"), MB_ICONERROR);
		命令行.ReleaseBuffer();
	}
}

// 获取进程ID
DWORD 登录页面类::获取进程ID(const wchar_t* 进程名)
{
	DWORD pid = 0;
	HANDLE 快照句柄 = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
	if (快照句柄 == INVALID_HANDLE_VALUE) return 0;

	PROCESSENTRY32 进程信息;
	进程信息.dwSize = sizeof(进程信息);

	BOOL 有进程 = Process32First(快照句柄, &进程信息);
	while (有进程)
	{
		if (_wcsicmp(进程信息.szExeFile, 进程名) == 0)
		{
			pid = 进程信息.th32ProcessID;
			break;
		}
		有进程 = Process32Next(快照句柄, &进程信息);
	}
	CloseHandle(快照句柄);
	return pid;
}

// 等待并安装窗口大小钩子（只有在复选框未选中时才调用）
void 登录页面类::等待并安装窗口大小钩子(const wchar_t* 监控进程名)
{
	DWORD pid = 0;
	HANDLE 目标进程句柄 = NULL;

	// 等待进程启动
	while (true)
	{
		pid = 获取进程ID(监控进程名);
		if (pid)
		{
			// 打开目标进程
			目标进程句柄 = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
			if (目标进程句柄 == NULL)
			{
				Sleep(1000);
				continue;
			}

			// 修改窗口大小,地址：0x5AAB1E 和 0x5AAB23
			BYTE 窗口高度代码[] = { 0x68, 0x00, 0x05, 0x00, 0x00 }; // push 328	/ push 500
			BYTE 窗口宽度代码[] = { 0x68, 0xC0, 0x03, 0x00, 0x00 }; // push 273	/ push 3C0

			// 写入内存
			SIZE_T 写入字节数;
			WriteProcessMemory(目标进程句柄, (LPVOID)0x5AAB1E, 窗口宽度代码, sizeof(窗口宽度代码), &写入字节数);
			WriteProcessMemory(目标进程句柄, (LPVOID)0x5AAB23, 窗口高度代码, sizeof(窗口高度代码), &写入字节数);

			CloseHandle(目标进程句柄);
			break;
		}
		Sleep(1000);
	}
}

void 登录页面类::等待并安装汇编钩子(const wchar_t* 监控进程名)
{
	DWORD pid = 0;
	HANDLE 目标进程句柄 = NULL;

	// 等待进程启动
	while (true)
	{
		pid = 获取进程ID(监控进程名);
		if (pid)
		{
			// 打开目标进程
			目标进程句柄 = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
			if (目标进程句柄 == NULL)
			{
				Sleep(1000);
				continue;
			}

			BYTE 账号光标X[] = { 0x68, 0x80, 0x02, 0x00, 0x00 }; // push 640
			BYTE 账号光标Y[] = { 0x68, 0x3B, 0x01, 0x00, 0x00 }; // push 315
			BYTE 密码光标X[] = { 0x68, 0x80, 0x02, 0x00, 0x00 }; // push 640
			BYTE 密码光标Y[] = { 0x68, 0x55, 0x01, 0x00, 0x00 }; // push 341

			BYTE 热键V修复[] = { 0x6A, 0x52 }; // push 52

			// 写入内存
			SIZE_T 写入字节数;

			WriteProcessMemory(目标进程句柄, (LPVOID)0x5863B3, 账号光标X, sizeof(账号光标X), &写入字节数);
			WriteProcessMemory(目标进程句柄, (LPVOID)0x5863AE, 账号光标Y, sizeof(账号光标Y), &写入字节数);
			WriteProcessMemory(目标进程句柄, (LPVOID)0x5863D0, 密码光标X, sizeof(密码光标X), &写入字节数);
			WriteProcessMemory(目标进程句柄, (LPVOID)0x5863CB, 密码光标Y, sizeof(密码光标Y), &写入字节数);

			WriteProcessMemory(目标进程句柄, (LPVOID)0x5BE894, 热键V修复, sizeof(热键V修复), &写入字节数);

			CloseHandle(目标进程句柄);
			break;
		}
		Sleep(1000);
	}
}

void 登录页面类::等待并安装标题钩子(const wchar_t* 监控进程名)
{
	TRACE(_T("标题钩子线程启动，开始等待游戏进程...\n"));

	DWORD pid = 0;
	HANDLE 目标进程句柄 = NULL;

	while (true)
	{
		pid = 获取进程ID(监控进程名);
		if (pid)
		{
			TRACE(_T("检测到游戏进程，PID: %d，开始安装标题钩子\n"), pid);

			目标进程句柄 = OpenProcess(PROCESS_ALL_ACCESS, FALSE, pid);
			if (目标进程句柄 == NULL)
			{
				TRACE(_T("打开进程失败，错误码: %d\n"), GetLastError());
				Sleep(1000);
				continue;
			}

			DWORD 目标地址 = 0x005B8AF2;

			// 使用 ANSI 字符串（多字节）
			const char* 自定义字符串 = "欢迎来到震撼美丽世界！    游戏QQ群：1079603650";
			size_t 字符串长度 = strlen(自定义字符串) + 1; // 包含结尾的\0

			// 分配远程内存
			BYTE* 远程字符串地址 = (BYTE*)VirtualAllocEx(目标进程句柄, NULL,
				字符串长度,
				MEM_COMMIT | MEM_RESERVE,
				PAGE_READWRITE);
			if (远程字符串地址 == NULL)
			{
				TRACE(_T("分配远程字符串内存失败，错误码: %d\n"), GetLastError());
				CloseHandle(目标进程句柄);
				Sleep(1000);
				continue;
			}

			// 写入 ANSI 字符串
			SIZE_T 写入字节数;
			if (!WriteProcessMemory(目标进程句柄, 远程字符串地址,
				自定义字符串, 字符串长度, &写入字节数))
			{
				TRACE(_T("写入字符串失败，错误码: %d\n"), GetLastError());
				VirtualFreeEx(目标进程句柄, 远程字符串地址, 0, MEM_RELEASE);
				CloseHandle(目标进程句柄);
				Sleep(1000);
				continue;
			}

			TRACE(_T("ANSI字符串已写入远程地址: 0x%08X，长度: %zu 字节\n"),
				(DWORD)远程字符串地址, 字符串长度);

			// mov ecx, 字符串地址
			BYTE 新指令[5] = { 0xB9 };
			*(DWORD*)(新指令 + 1) = (DWORD)远程字符串地址;

			// 修改内存保护并写入
			DWORD 旧保护;
			VirtualProtectEx(目标进程句柄, (LPVOID)目标地址, 5, PAGE_EXECUTE_READWRITE, &旧保护);

			if (!WriteProcessMemory(目标进程句柄, (LPVOID)目标地址, 新指令, 5, &写入字节数))
			{
				TRACE(_T("修改目标地址指令失败，错误码: %d\n"), GetLastError());
				VirtualProtectEx(目标进程句柄, (LPVOID)目标地址, 5, 旧保护, &旧保护);
				VirtualFreeEx(目标进程句柄, 远程字符串地址, 0, MEM_RELEASE);
				CloseHandle(目标进程句柄);
				Sleep(1000);
				continue;
			}

			VirtualProtectEx(目标进程句柄, (LPVOID)目标地址, 5, 旧保护, &旧保护);

			TRACE(_T("标题钩子安装成功！新字符串地址: 0x%08X\n"), (DWORD)远程字符串地址);

			CloseHandle(目标进程句柄);
			break;
		}
		Sleep(1000);
	}
}

